// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {CVXStaker, ICVXBooster, IERC20} from "../src/CVXStaker.sol";

contract InvMutTest is Test {
    CVXStaker c;

    function setUp() public { c = new CVXStaker(address(new __InvMutHandleStub()), IERC20(address(this)), ICVXBooster(address(this)), new address[](0)); }

    function testFuzz_property(address newOwner) public {
        // Only the zero address is outside the admissible domain: ownership can
        // legitimately be transferred to ANY nonzero address in the reference.
        vm.assume(newOwner != address(0));

        // The caller must be the current owner for the call to reach the require.
        vm.prank(c.owner());
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for EVERY nonzero newOwner, transferOwnership succeeds
        // and c.owner() becomes exactly newOwner. The mutant reverts for all
        // nonzero newOwner, so ok is false there and owner stays unchanged.
        assertTrue(ok && c.owner() == newOwner);
    }
}
